std::vector<int> data = {1, 2, 3, 4, 5};

// 1. Traditional Forward Traversal and Modification
for (auto it = data.begin(); it != data.end(); ++it) {
    *it *= 10;
}

// 2. Const and Reverse Iterators
std::list<int> L = {1, 2, 3};
for (auto cit = L.cbegin(); cit != L.cend(); ++cit) {} // Read-only access
for (auto rit = L.rbegin(); rit != L.rend(); ++rit) {} // Reverse traversal

// 3. Iterator Range in Algorithms
auto it_start = data.begin() + 1; // Not available for all containers (e.g., list)
auto it_end = data.end();
auto it_found = std::find(it_start, it_end, 30);

if (it_found != data.end()) {
    data.erase(it_found);
}
